<?php
namespace App\Http\Controllers;
use App\Models\{Product,Category,Unit,BusinessUnit,StockBalance,StockMovement}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductController extends Controller
{
 public function index(Request $r){$products=Product::with(['category','baseUnit','businessUnit','stock'])->when($r->q,fn($q)=>$q->where('name','like','%'.$r->q.'%')->orWhere('sku','like','%'.$r->q.'%'))->latest()->paginate(20)->withQueryString(); return view('products.index',compact('products'));}
 public function create(){return view('products.create',['categories'=>Category::orderBy('name')->get(),'units'=>Unit::where('is_active',1)->orderBy('name')->get(),'businessUnits'=>BusinessUnit::where('is_active',1)->get()]);}
 public function store(Request $r){$d=$r->validate(['opening_quantity'=>'nullable|numeric|min:0','name'=>'required|string|max:190','sku'=>'nullable|string|max:80|unique:products,sku','barcode'=>'nullable|string|max:100|unique:products,barcode','category_id'=>'nullable|exists:categories,id','business_unit_id'=>'nullable|exists:business_units,id','base_unit_id'=>'required|exists:units,id','purchase_price'=>'required|numeric|min:0','sale_price'=>'required|numeric|min:0','alert_quantity'=>'nullable|numeric|min:0','attributes'=>'nullable|string']); $d['attributes']=filled($d['attributes']??null)?json_decode($d['attributes'],true):null;$opening=(float)($d['opening_quantity']??0);unset($d['opening_quantity']);DB::transaction(function()use($d,$opening){$p=Product::create($d);if($opening>0){StockBalance::create(['product_id'=>$p->id,'product_variant_id'=>null,'quantity'=>$opening,'avg_cost'=>$p->purchase_price]);StockMovement::create(['product_id'=>$p->id,'reference_type'=>'opening_stock','reference_id'=>$p->id,'direction'=>'in','quantity'=>$opening,'unit_cost'=>$p->purchase_price,'unit_name'=>$p->baseUnit->short_name,'note'=>'Opening stock','user_id'=>auth()->id()]);}}); return redirect()->route('products.index')->with('success','Product added.');}
 public function edit(Product $product){return view('products.edit',['product'=>$product,'categories'=>Category::orderBy('name')->get(),'units'=>Unit::where('is_active',1)->get(),'businessUnits'=>BusinessUnit::where('is_active',1)->get()]);}
 public function update(Request $r,Product $product){$d=$r->validate(['name'=>'required|string|max:190','sku'=>'nullable|string|max:80|unique:products,sku,'.$product->id,'barcode'=>'nullable|string|max:100|unique:products,barcode,'.$product->id,'category_id'=>'nullable|exists:categories,id','business_unit_id'=>'nullable|exists:business_units,id','base_unit_id'=>'required|exists:units,id','purchase_price'=>'required|numeric|min:0','sale_price'=>'required|numeric|min:0','alert_quantity'=>'nullable|numeric|min:0','attributes'=>'nullable|string']);$d['attributes']=filled($d['attributes']??null)?json_decode($d['attributes'],true):null;$product->update($d);return redirect()->route('products.index')->with('success','Product updated.');}
 public function destroy(Product $product){if($product->stockMovements()->exists())return back()->withErrors(['product'=>'Product has stock history and cannot be deleted.']);$product->delete();return back()->with('success','Product deleted.');}
}
